void CescToolPage::initializeServices()
{
 const auto caps=m_context->cescSession()->capabilities();
 m_configurationAvailable=false;
 if(caps&(Cesc::MotorService|Cesc::SensorService))m_stateTimer->start();
 if(caps&Cesc::MotorService)m_context->cescMotorClient()->requestState();
 if(caps&Cesc::ConfigurationService){
  m_configOperation->setText(tr("正在读取设备配置…"));
  m_context->cescConfigurationClient()->readConfiguration();
 }else{
  m_configOperation->setText(tr("当前设备固件不支持配置服务"));
  m_saveText->setText(tr("不支持配置保存状态查询"));
 }
}
CescToolPage::~CescToolPage(){if(m_running&&m_context->cescSession()->isReady())m_context->cescMotorClient()->stop();}

